// infix: можно вызывать без точки и скобок
// Условия: функция-член или расширение, ОДИН параметр, без значения по умолчанию
infix fun Int.veya(digeri: Int) = "($this, $digeri)"

infix fun Int.vur(k: Int) = this * k

