// tailrec говорит компилятору: преврати эту рекурсию в цикл
tailrec fun faktorial(n: Int, akkumulyator: Long = 1): Long =
    if (n <= 1) akkumulyator else faktorial(n - 1, akkumulyator * n)

tailrec fun cemle(n: Long, akk: Long = 0): Long =
    if (n == 0L) akk else cemle(n - 1, akk + n)

fun main() {
    println(faktorial(10))
    // Нет StackOverflowError даже на глубине 1 миллион
    println("StackOverflow olmadan: ${cemle(1_000_000)}")
}

