class Hesab(private val sahib: String, private var balans: Double = 0.0) {

    fun tanit() = println("Salam, mən ${sahib}əm")

    fun medaxil(mebleg: Double) {
        require(mebleg > 0) { "Məbləğ müsbət olmalıdır" }
        balans += mebleg
        println("Balans: $balans")
    }

    fun mexaric(mebleg: Double): Boolean {
        if (mebleg > balans) {
            println("Kifayət qədər vəsait yoxdur")
            return false
        }
        balans -= mebleg
        println("Balans: $balans")
        return true
    }
}

