open class Heyvan
class It : Heyvan()

// out — производитель (producer): только возвращает T
class Menbe<out T>(private val deyer: T) {
    fun al(): T = deyer
    // fun yaz(x: T) { }    ← ОШИБКА: out-тип не может быть параметром
}

// in — потребитель (consumer): только принимает T
class Hedef<in T> {
    fun yaz(deyer: T) = println(deyer)
    // fun al(): T          ← ОШИБКА: in-тип нельзя возвращать
}

fun main() {
    val itMenbe: Menbe<It> = Menbe(It())
    val heyvanMenbe: Menbe<Heyvan> = itMenbe      // работает благодаря out

    val heyvanHedef: Hedef<Heyvan> = Hedef()
    val itHedef: Hedef<It> = heyvanHedef          // работает благодаря in

    // MutableList инвариантен:
    // val a: MutableList<Heyvan> = mutableListOf<It>()  ← ОШИБКА
    // Причина: тогда туда можно было бы добавить Pisik!

    // А List ковариантен (List<out E>) — читать безопасно:
    val b: List<Heyvan> = listOf<It>()            // работает
}

// без reified: "Cannot check for instance of erased type: T"
inline fun <reified T> List<*>.yalnizTipi(): List<T> =
    filterIsInstance<T>()

inline fun <reified T> tipdirmi(deyer: Any): Boolean = deyer is T

fun main() {
