fun main() = runBlocking {
    val is1 = launch {
        try {
            repeat(100) { i ->
                println("İşlənir $i")
                delay(100)          // точка, чувствительная к отмене
            }
        } catch (e: CancellationException) {
            println("Ləğv olundu")
            throw e                 // ОБЯЗАТЕЛЬНО пробросить дальше
        } finally {
            // withContext(NonCancellable) { ... } — если очистка suspend
