data class Isci(val ad: String, val sobe: String, val maas: Int)

fun main() {
    val iscilder = listOf(
        Isci("Aysel", "IT", 3000),
        Isci("Kamran", "IT", 3500),
        Isci("Leyla", "Satış", 2000)
    )

    val ortaMaas = iscilder
        .filter { it.maas > 2500 }
        .groupBy { it.sobe }
        .mapValues { (_, siyahi) -> siyahi.map { it.maas }.average() }

    ortaMaas.forEach { (sobe, orta) ->
        println("$sobe: $orta")
    }
}

record Isci(String ad, String sobe, int maas) {}

public class Main {
    public static void main(String[] args) {
        List<Isci> iscilder = List.of(
            new Isci("Aysel", "IT", 3000),
            new Isci("Kamran", "IT", 3500),
            new Isci("Leyla", "Satis", 2000)
        );

        Map<String, Double> ortaMaas = iscilder.stream()
            .filter(i -> i.maas() > 2500)
            .collect(Collectors.groupingBy(
                Isci::sobe,
                Collectors.averagingInt(Isci::maas)
            ));

        ortaMaas.forEach((sobe, orta) ->
            System.out.println(sobe + ": " + orta));
    }
}

